// Clean and format AI responses for all incoming items
const allAiItems = $input.all();
const originalItems = $('Prepare AI Prompts').all();

const output = [];

allAiItems.forEach((aiItem, index) => {
  const originalItem = originalItems[index]?.json || {};
  const aiResponse = aiItem.json?.choices?.[0]?.message?.content || '{}';

  let parsed = {};
  try {
    parsed = JSON.parse(aiResponse);
  } catch (e) {
    const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try { parsed = JSON.parse(jsonMatch[0]); } catch {}
    }
  }

  // Support both multi-offer array ({ is_special: true, offers: [...] }) and legacy single-offer schema
  let offers = [];
  if (Array.isArray(parsed.offers) && parsed.offers.length > 0) {
    offers = parsed.offers;
  } else if (parsed.is_special !== false && (parsed.year || parsed.monthly_payment || parsed.apr || parsed.selling_price || parsed.offer_details)) {
    offers = [parsed];
  }

  // Discard if classified as non-special branding or no valid offers
  if (offers.length === 0 || parsed.is_special === false) {
    output.push({
      json: {
        staging_id: originalItem.id,
        image_hash: originalItem.imageHash || null,
        auto_approve: false,
        status: 'discarded',
        discard: true,
        discard_reason: 'Classified as non-special branding or no valid numeric offers',
        raw_text: originalItem.rawText || '',
        extracted_data: { is_special: false }
      }
    });
    return;
  }

  // Map each offer into an individual approved item
  offers.forEach((offer, idx) => {
    let cleanMonthly = offer.monthly_payment != null && offer.monthly_payment !== '' ? Number(offer.monthly_payment) : null;
    let cleanApr = offer.apr != null && offer.apr !== '' ? Number(offer.apr) : null;
    let cleanType = (offer.special_type || 'lease').toLowerCase().trim();
    let cleanSellingPrice = offer.selling_price != null && offer.selling_price !== '' ? Number(offer.selling_price) : null;
    let cleanMsrp = offer.msrp != null && offer.msrp !== '' ? Number(offer.msrp) : cleanSellingPrice;
    let cleanDown = offer.down_payment != null && offer.down_payment !== '' ? Number(offer.down_payment) : null;
    let cleanDas = offer.due_at_signing != null && offer.due_at_signing !== '' ? Number(offer.due_at_signing) : null;
    let cleanTerm = offer.term_months != null && offer.term_months !== '' ? Number(offer.term_months) : null;
    let cleanOfferDetails = offer.offer_details ? String(offer.offer_details).trim() : null;

    // Sanitize disclosure factors (e.g., "$16.67 per $1,000 financed")
    const discText = `${offer.title || ''} ${offer.disclaimer || ''} ${originalItem.rawText || ''}`.toLowerCase();
    if (cleanMonthly != null && cleanMonthly < 80) {
      if (
        cleanApr != null ||
        discText.includes('per $1,000') ||
        discText.includes('per $1000') ||
        discText.includes('per thousand') ||
        discText.includes('per 1,000') ||
        discText.includes('per 1000')
      ) {
        cleanMonthly = null;
        if (cleanApr != null) {
          cleanType = 'apr';
        }
      }
    }

    // Fallback extraction for cash / discount / savings specials (e.g. "Save $3,500", "$4,000 cash back")
    const combinedDisc = `${cleanOfferDetails || ''} ${offer.title || ''} ${offer.disclaimer || ''} ${originalItem.rawText || ''}`;
    if (!cleanOfferDetails && cleanMonthly == null && (cleanApr == null || cleanApr === 0)) {
      const discMatch =
        combinedDisc.match(/(?:save|saving|savings|discount|off|cash back|bonus cash|rebate|customer cash)\s*(?:up to\s*)?[:\$]?\s*\$?([0-9]{1,2},[0-9]{3}|[0-9]{3,5})/i) ||
        combinedDisc.match(/\$([0-9]{1,2},[0-9]{3}|[0-9]{3,5})\s*(?:off|savings|discount|cash back|bonus cash|rebate|total savings|customer cash)/i) ||
        combinedDisc.match(/(?:save|discount|off|cash back|rebate)\s*(?:up to\s*)?\$?([0-9]{1,2},[0-9]{3}|[0-9]{3,5})/i);
      if (discMatch && discMatch[1]) {
        const num = parseInt(discMatch[1].replace(/,/g, ''), 10);
        if (num >= 300 && num <= 25000) {
          let tag = 'OFF';
          if (/cash back|bonus cash/i.test(combinedDisc)) tag = 'CASH BACK';
          else if (/gas card/i.test(combinedDisc)) tag = 'GAS CARD';
          cleanOfferDetails = `$${num.toLocaleString()} ${tag}`;
          cleanType = 'discount';
        }
      }
    } else if (cleanOfferDetails && (cleanType === 'cash' || cleanType === 'lease') && !cleanMonthly && !cleanApr) {
      if (/off|save|savings|discount|cash back|rebate/i.test(cleanOfferDetails)) {
        cleanType = 'discount';
      }
    }

    const hasNumericTerms = (
      (cleanMonthly != null && cleanMonthly > 0) ||
      (cleanApr != null && cleanApr >= 0) ||
      (cleanDown != null && cleanDown >= 0) ||
      (cleanTerm != null && cleanTerm > 0) ||
      (cleanMsrp != null && cleanMsrp > 0) ||
      (cleanSellingPrice != null && cleanSellingPrice > 0) ||
      (cleanOfferDetails && String(cleanOfferDetails).trim().length > 0)
    );

    const isSpecial = hasNumericTerms;

    output.push({
      json: {
        staging_id: originalItem.id,
        offer_index: idx + 1,
        image_hash: originalItem.imageHash || null,
        auto_approve: isSpecial,
        status: isSpecial ? 'approved' : 'discarded',
        discard: !isSpecial,
        discard_reason: !isSpecial ? 'No actionable financial special terms (empty card avoided)' : null,
        raw_text: originalItem.rawText || '',
        extracted_data: {
          is_special: isSpecial,
          offer_index: idx + 1,
          year: offer.year || new Date().getFullYear(),
          make: offer.make || 'Unknown',
          model: offer.model || 'Special Offer',
          trim: offer.trim || null,
          special_type: cleanType,
          monthly_payment: cleanMonthly,
          term_months: cleanTerm,
          down_payment: cleanDown,
          due_at_signing: cleanDas,
          apr: cleanApr,
          msrp: cleanMsrp,
          selling_price: cleanSellingPrice,
          offer_details: cleanOfferDetails || null,
          title: offer.title || originalItem.title || '',
          disclaimer: offer.disclaimer || originalItem.disclaimer || '',
          expiration_date: offer.expiration_date || null
        }
      }
    });
  });
});

return output;
